('17000000-0000-4000-8000-000000000001', 'research-17000000-0000-4000-8000-000000000001', 'published', 'synthetic', '{"title": "Экологические профессии: как выбрать направление", "summary": "Сравните задачи в полевых проектах, аналитике и экологическом просвещении.", "category": "Карьера", "author": "Демонстрационная редакция OpenMentor", "publishedOn": "2026-11-01", "readingMinutes": 5, "coverUrl": "/research-assets/ecology-careers.svg", "coverAlt": "Учебная иллюстрация экологических карьер", "pdfUrl": "/research-assets/sample-research.pdf", "sections": [{"id": "about", "title": "Об этом материале", "body": "Это синтетический демонстрационный материал для проверки каталога и редактора. Он не является результатом эмпирического исследования и не содержит измеренных результатов.\n\nСравните задачи в полевых проектах, аналитике и экологическом просвещении."}, {"id": "practice", "title": "Вопросы для самостоятельной работы", "body": "Начните с описания интересующих задач, а не с названия должности.\n\nЗапишите вопросы к наставнику, обозначьте ограничения и выберите небольшой учебный проект. Проверяйте актуальные требования по первичным источникам."}], "keyFindings": ["Начните с описания интересующих задач, а не с названия должности.", "Показывайте происхождение примеров и ограничения своего опыта."], "citation": "Синтетический учебный пример OpenMentor; не научная публикация."}'::jsonb),
('17000000-0000-4000-8000-000000000002', 'research-17000000-0000-4000-8000-000000000002', 'published', 'synthetic', '{"title": "Портфолио начинающего эколога", "summary": "Учебный маршрут для подготовки первого портфолио без вымышленных достижений.", "category": "Навыки", "author": "Демонстрационная редакция OpenMentor", "publishedOn": "2026-11-01", "readingMinutes": 5, "coverUrl": "/research-assets/ecology-careers.svg", "coverAlt": "Учебная иллюстрация экологических карьер", "pdfUrl": "/research-assets/sample-research.pdf", "sections": [{"id": "about", "title": "Об этом материале", "body": "Это синтетический демонстрационный материал для проверки каталога и редактора. Он не является результатом эмпирического исследования и не содержит измеренных результатов.\n\nУчебный маршрут для подготовки первого портфолио без вымышленных достижений."}, {"id": "practice", "title": "Вопросы для самостоятельной работы", "body": "Отделяйте учебные упражнения от выполненных для заказчика проектов.\n\nЗапишите вопросы к наставнику, обозначьте ограничения и выберите небольшой учебный проект. Проверяйте актуальные требования по первичным источникам."}], "keyFindings": ["Отделяйте учебные упражнения от выполненных для заказчика проектов.", "Показывайте происхождение примеров и ограничения своего опыта."], "citation": "Синтетический учебный пример OpenMentor; не научная публикация."}'::jsonb),
